// 18-tap FIR, TRANSPOSED direct form: one multiply + one add per stage, so the
// register-to-register critical path is independent of tap count -> high Fmax.
// Same transfer function as the direct form (equivalent up to a fixed latency).
module firr18_v5 (
    input  wire        clk,
    input  wire        rst_n,
    input  wire [7:0]  x,
    output reg  [15:0] y
);
    reg  [23:0] a0, a1, a2, a3, a4, a5, a6, a7, a8, a9, a10, a11, a12, a13, a14, a15, a16, a17;
    always @(posedge clk) begin
        if (!rst_n) begin
            a0 <= 24'd0; a1 <= 24'd0; a2 <= 24'd0; a3 <= 24'd0; a4 <= 24'd0; a5 <= 24'd0; a6 <= 24'd0; a7 <= 24'd0; a8 <= 24'd0; a9 <= 24'd0; a10 <= 24'd0; a11 <= 24'd0; a12 <= 24'd0; a13 <= 24'd0; a14 <= 24'd0; a15 <= 24'd0; a16 <= 24'd0; a17 <= 24'd0; y <= 16'd0;
        end else begin
            a0 <= 24'd2 + 8'd3 * x + a1;
            a1 <= 24'd4 + 8'd7 * x + a2;
            a2 <= 24'd6 + 8'd11 * x + a3;
            a3 <= 24'd8 + 8'd15 * x + a4;
            a4 <= 24'd10 + 8'd19 * x + a5;
            a5 <= 24'd12 + 8'd23 * x + a6;
            a6 <= 24'd14 + 8'd27 * x + a7;
            a7 <= 24'd16 + 8'd31 * x + a8;
            a8 <= 24'd18 + 8'd35 * x + a9;
            a9 <= 24'd20 + 8'd39 * x + a10;
            a10 <= 24'd22 + 8'd43 * x + a11;
            a11 <= 24'd24 + 8'd47 * x + a12;
            a12 <= 24'd26 + 8'd51 * x + a13;
            a13 <= 24'd28 + 8'd55 * x + a14;
            a14 <= 24'd30 + 8'd59 * x + a15;
            a15 <= 24'd32 + 8'd63 * x + a16;
            a16 <= 24'd34 + 8'd67 * x + a17;
            a17 <= 24'd36 + 8'd71 * x;
            y <= a0[15:0];
        end
    end
endmodule
